#include <cstdio>
#include <vector>
using namespace std;

int main() {
    int n, m;
    if (scanf("%d%d", &n, &m) != 2) return 0;

    vector<vector<char>> c(n, vector<char>(m));
    vector<bool> row(n, false), col(m, false);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            scanf(" %c", &c[i][j]);
            if (c[i][j] == 'S') {
                row[i] = true;
                col[j] = true;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            if (!row[i] || !col[j])
                ++ans;

    printf("%d", ans);
    return 0;
}

